-- Apply only to a dedicated SoloStack project; never run on unrelated projects.
create table if not exists public.tool_click_events (id bigint generated by default as identity primary key, tool_slug text not null check (tool_slug ~ '^[a-z0-9-]{1,80}$'), destination_host text not null check (char_length(destination_host) between 3 and 253), page_path text not null check (char_length(page_path) between 1 and 300), created_at timestamptz not null default now());
alter table public.tool_click_events enable row level security;
revoke all on table public.tool_click_events from anon, authenticated;
grant insert on table public.tool_click_events to anon, authenticated;
grant usage, select on sequence public.tool_click_events_id_seq to anon, authenticated;
drop policy if exists "anonymous can record outbound clicks" on public.tool_click_events;
create policy "anonymous can record outbound clicks" on public.tool_click_events for insert to anon with check (char_length(tool_slug) between 1 and 80 and char_length(destination_host) between 3 and 253 and char_length(page_path) between 1 and 300);
-- No public SELECT policy is created.